   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="热菜汤、面包都准备好了，大家快下来吃饭吧——！", msg_color="", msg_size=0, talker="男孩", audio="", img="arts/ui/bg/story/storybg_14_111.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="别叫了，臭小子，我们马上下来。", msg_color="", msg_size=0, talker="船坞工人", audio="", img="arts/ui/bg/story/storybg_14_111.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7201", 0, 0, -22.5, 219.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="甲板上传来了回应，工人们放下了手中的工具，擦了擦身上被寒风吹进来的雪屑，排队从升降梯处离开破冰船。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_111.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="寒风从船坞的缝隙里灌进来，卷起地上的碎冰碴，打在工人们的脸上，疼得他们忍不住皱眉。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_111.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
