   [201]={next_id=202, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="带他来的工人，继续维修破冰船，扣除今天的所有薪水，以示惩戒。", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_111.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
