   [234]={next_id=235, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="原来您都知道……那您为什么不阻止我？", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "7196", 0, 0, 27, 218},{ 3, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
