   [242]={next_id=243, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这是……禁区的构造图！", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [243]={next_id=244, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="没错，这份地图远比你自己绘制的精细，对你来说应该会有很大的作用。", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [244]={next_id=245, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="将军，所以你的意思是……允许我去禁区吗？", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [245]={next_id=246, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="将军轻点头，没等涅普露惊喜出声，就抬手打断了她。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [246]={next_id=247, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="听我把话说完。你想进入禁区找燃料，我同意，但是有一个前提——", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [247]={next_id=248, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这是一场绝对隐秘的行动，不能留下任何与卫队、与我有关的痕迹。", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [248]={next_id=249, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……我明白，没有帝国的明令许可，私自闯入军事禁区，是要按叛国罪论处的，更何况是伊凡城这个敏感的地方……", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [249]={next_id=250, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你明白就好。", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [250]={next_id=251, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="将军的目光扫过她，带着一丝不易察觉的疲惫。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [251]={next_id=252, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="伯基索米不信任伊凡城，更不信任我这个当年“平叛不力”的将军。派来的那个副官，名义上是协助防务，实则是监视我的一举一动。", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [252]={next_id=253, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我的身份太敏感，伊凡城的卫队也不能再承受任何非议。所以，这次行动，你只能靠自己。", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [253]={next_id=254, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="无论你在禁区里遇到什么——是被困住，是遭遇污染甚至是死在里面……我都不会派人去救你。对外，我会宣称你是私自行动，与卫队无关。", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [254]={next_id=255, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这番话像一块冰，砸在涅普露身上，而当她看到将军眼里的挣扎，逐渐理解了他的用意。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [255]={next_id=256, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她深吸一口气，挺直了脊背，脸上褪去了之前的慌乱，只剩下坚定。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [256]={next_id=257, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我懂了，将军。我已经做好了准备。", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
